frappe.ui.form.on('Purchase Order', {
	refresh: function(frm) {
		frm.trigger("add_create_term_payment_request_button");
	},

    add_create_term_payment_request_button: function(frm){
        if (frm.doc.payment_schedule){
            frm.add_custom_button(__("Payment Term Request"), function(){frm.trigger("show_payment_request_dialog");}, __("Create"));
        }
    },

    after_save: function(frm){
        frm.trigger("add_create_term_payment_request_button");
    },

    show_payment_request_dialog: function(frm){
        let due_date_options = [];
        for (var i = 0; i < frm.doc.payment_schedule.length; ++i){
            if(!frm.doc.payment_schedule[i].paid_amount || frm.doc.payment_schedule[i].paid_amount == 0){
                due_date_options.push({"label": frm.doc.payment_schedule[i].due_date, "value": i});
            }
        }

        if (due_date_options){
            frm.payment_request_dialog = new frappe.ui.Dialog({
                title: __("Payment Term Request"),
                fields: [
                    {
                        label: __("Due Date"),
                        fieldname: "due_date",
                        fieldtype: "Select",
                        options: due_date_options,
                        change: function(){
                            frm.payment_request_dialog.set_value("payment_amount", frm.doc.payment_schedule[this.value].payment_amount);
                            frm.payment_request_dialog.set_value("invoice_portion", frm.doc.payment_schedule[this.value].invoice_portion);
                        },
                    },
                    {
                        label: __("Payment Amount"),
                        fieldname: "payment_amount",
                        fieldtype: "Currency",
                        options: frm.doc.currency,
                        read_only: 1,
                    },
                    {
                        label: __("Amount"),
                        fieldname: "amount",
                        fieldtype: "Currency",
                    },
                ],
                primary_action_label: __("Create Payment Requst"),
                primary_action(values) {
                    if (values["amount"] <= 0 || values["amount"] > values["payment_amount"]){
                        frappe.msgprint(__('Amount must be less or equal to Payment Amount'));
                        return;
                    }
                    frappe.call({
                        method: "pav.pav.utils.make_payment_request",
                        args:{
                            payment_request_type: "Outward",
                            grand_total: values["amount"], 
                            dt: me.frm.doc.doctype,
            				dn: me.frm.doc.name,
            				recipient_id: me.frm.doc.contact_email,
            				party_type: "Supplier",
            				party: frm.doc.supplier,
                        },
                        callback: function(r){
                            if(!r.exc){
            					var doc = frappe.model.sync(r.message);
            					frappe.set_route("Form", r.message.doctype, r.message.name);
            				}
                        }
                    });
                   frm.payment_request_dialog.hide();
                }
            });
            frm.payment_request_dialog.show();
        }
    },
})

